namespace alis {
struct DfmRunSettings {
    TerrainParameters parameters; // Dialog values are METRES; convert once at the controller boundary.
    QSet<int> buildingClasses{6,128,129};
    QJsonObject toJson() const {QJsonArray classes;for(int c:buildingClasses)classes.append(c);const auto& p=parameters;return {{"step",p.gridStep},{"minimumMerge",p.dfmMinimumMerge},{"classes",classes},{"fillMethod",int(p.dfmFill.method)},{"radius",p.dfmFill.radius},{"range",p.dfmFill.maximumLocalRange},{"deviation",p.dfmFill.maximumMeanDeviation},{"minSupport",int(p.dfmFill.minimumSupport)},{"maxSupport",int(p.dfmFill.maximumSupport)},{"surrounding",p.dfmFill.requireSurroundingSupport},{"maxEdge",p.maximumInterpolationEdgeLength},{"krigingKNN",p.krigingNeighbours},{"krigingModel",p.krigingModel},{"krigingAuto",p.krigingAutoParameters},{"krigingRange",p.krigingRange},{"krigingSill",p.krigingSill},{"krigingNugget",p.krigingNugget}};}
};
inline DfmRunSettings dfmRunSettings(const QJsonObject& json,double initialStep){DfmRunSettings out;auto& p=out.parameters;p.surfaceMaximum=true;p.requireConflictReview=true;p.gridStep=json.value("step").toDouble(initialStep);p.dfmMinimumMerge=json.value("minimumMerge").toBool(true);p.dfmFill.method=DfmFillMethod(json.value("fillMethod").toInt(1));p.dfmFill.radius=json.value("radius").toDouble(4*p.gridStep);p.dfmFill.maximumLocalRange=json.value("range").toDouble(1);p.dfmFill.maximumMeanDeviation=json.value("deviation").toDouble(.25);p.dfmFill.minimumSupport=unsigned(json.value("minSupport").toInt(4));p.dfmFill.maximumSupport=unsigned(json.value("maxSupport").toInt(16));p.dfmFill.requireSurroundingSupport=json.value("surrounding").toBool(true);p.maximumInterpolationEdgeLength=json.value("maxEdge").toDouble(4*p.gridStep);p.krigingNeighbours=json.value("krigingKNN").toInt(8);p.krigingModel=json.value("krigingModel").toInt(0);p.krigingAutoParameters=json.value("krigingAuto").toBool(true);p.krigingRange=json.value("krigingRange").toDouble(10);p.krigingSill=json.value("krigingSill").toDouble(1);p.krigingNugget=json.value("krigingNugget").toDouble(0);if(json.contains("classes")){out.buildingClasses.clear();for(auto c:json.value("classes").toArray())if(c.toInt()==6||c.toInt()==128||c.toInt()==129)out.buildingClasses.insert(c.toInt());}p.interpolateEmptyCells=p.dfmFill.method!=DfmFillMethod::None;return out;}
inline bool dfmSettingsDialog(DfmRunSettings& settings,QWidget* parent){
    QDialog dialog(parent);dialog.setWindowTitle("ALiS — DFM stages and void interpolation");dialog.resize(640,760);auto* root=new QVBoxLayout(&dialog);auto* scroll=new QScrollArea;scroll->setWidgetResizable(true);auto* content=new QWidget;auto* form=new QFormLayout(content);form->setRowWrapPolicy(QFormLayout::WrapLongRows);scroll->setWidget(content);root->addWidget(scroll);
    auto* note=new QLabel("Preset MIN: raster Ground to minimum Z WITHOUT fill; raster chosen Building classes to minimum Z WITHOUT fill; merge the two cell clouds and raster minimum Z again; interpolate ONLY remaining voids. All stages use one common step/origin, so intermediate grids are evaluated without making full-cloud copies. WARNING: in a shared Ground/roof cell the final MIN chooses Ground and can erase the roof. The alternative preset preserves Building maxima.");note->setWordWrap(true);note->setMaximumWidth(590);form->addRow(note);
    auto* mode=new QComboBox;mode->addItem("MIN Ground + MIN Building → merged MIN",true);mode->addItem("MIN Ground / MAX Building (Building priority)",false);mode->setCurrentIndex(settings.parameters.dfmMinimumMerge?0:1);form->addRow("DFM recipe",mode);
    auto* step=new QDoubleSpinBox;step->setDecimals(4);step->setRange(.0001,10000);step->setValue(settings.parameters.gridStep);form->addRow("Common cell step (m)",step);
    QList<QCheckBox*> classes;for(auto item:QList<QPair<int,QString>>{{6,"Building (6)"},{128,"Roofs (128)"},{129,"Vertical walls (129)"}}){auto* check=new QCheckBox(item.second);check->setChecked(settings.buildingClasses.contains(item.first));check->setProperty("code",item.first);classes<<check;form->addRow(check);}
    auto* method=new QComboBox;method->setMinimumContentsLength(18);method->setSizeAdjustPolicy(QComboBox::AdjustToMinimumContentsLengthWithIcon);method->addItem("No interpolation — keep NODATA",0);method->addItem("Local mean — closest to its supporting local mean",1);method->addItem("Inverse distance (IDW), locally guarded",2);method->addItem("TIN / Delaunay linear, locally guarded",3);method->addItem("Kriging (native ordinary), locally guarded",4);method->setCurrentIndex(method->findData(int(settings.parameters.dfmFill.method)));form->addRow("Final void fill",method);
    auto number=[&](const QString& label,double value,double minimum=0.){auto* spin=new QDoubleSpinBox;spin->setDecimals(4);spin->setRange(minimum,100000);spin->setValue(value);form->addRow(label,spin);return spin;};
    auto* radius=number("Maximum support distance (m)",settings.parameters.dfmFill.radius,.0001);auto* range=number("Maximum local elevation range (m)",settings.parameters.dfmFill.maximumLocalRange);auto* deviation=number("Maximum distance from local mean (m)",settings.parameters.dfmFill.maximumMeanDeviation);auto* edge=number("Delaunay maximum triangle edge (m; 0 unlimited)",settings.parameters.maximumInterpolationEdgeLength);
    auto* minSupport=new QSpinBox;minSupport->setRange(3,256);minSupport->setValue(int(settings.parameters.dfmFill.minimumSupport));form->addRow("Minimum observed supporting cells",minSupport);auto* maxSupport=new QSpinBox;maxSupport->setRange(3,256);maxSupport->setValue(int(settings.parameters.dfmFill.maximumSupport));form->addRow("Nearest observed cells used (maximum)",maxSupport);
    auto* knn=new QSpinBox;knn->setRange(3,64);knn->setValue(settings.parameters.krigingNeighbours);form->addRow("Kriging nearest neighbours",knn);auto* model=new QComboBox;model->addItems({"Spherical","Exponential","Gaussian"});model->setCurrentIndex(settings.parameters.krigingModel);form->addRow("Kriging variogram model",model);auto* autoVariogram=new QCheckBox("Estimate variogram parameters automatically (review required)");autoVariogram->setChecked(settings.parameters.krigingAutoParameters);form->addRow(autoVariogram);
    auto* krange=number("Kriging correlation range (m)",settings.parameters.krigingRange,.0001);auto* sill=number("Kriging sill (m²)",settings.parameters.krigingSill,.0001);auto* nugget=number("Kriging nugget (m²)",settings.parameters.krigingNugget);
    auto* surrounding=new QCheckBox("Require observed support surrounding the void (no edge extension)");surrounding->setChecked(settings.parameters.dfmFill.requireSurroundingSupport);form->addRow(surrounding);
    auto* explanation=new QLabel("Only original observed cells support interpolation: filled cells never feed the next fill. Observed elevations are not smoothed or changed. Too few neighbours, large discontinuities, excessive mean deviation or missing surrounding support leave NODATA. Local mean has zero deviation from the selected neighbours' arithmetic mean, NOT guaranteed accuracy: it may flatten slopes and roof edges. IDW/Delaunay estimates exceeding the mean-deviation limit are rejected, not clipped. Inspect the source-quality field and rejection counts.");explanation->setWordWrap(true);explanation->setMaximumWidth(590);form->addRow(explanation);
    auto update=[&](){const bool fill=method->currentData().toInt()!=0,kriging=method->currentData().toInt()==4;for(QWidget* w:{static_cast<QWidget*>(radius),static_cast<QWidget*>(range),static_cast<QWidget*>(deviation),static_cast<QWidget*>(minSupport),static_cast<QWidget*>(maxSupport),static_cast<QWidget*>(surrounding)})w->setEnabled(fill);edge->setEnabled(method->currentData().toInt()==3);minSupport->setMinimum(kriging?knn->value():3);if(maxSupport->value()<minSupport->value())maxSupport->setValue(minSupport->value());knn->setEnabled(kriging);model->setEnabled(kriging);autoVariogram->setEnabled(kriging);for(auto* spin:{krange,sill,nugget})spin->setEnabled(kriging&&!autoVariogram->isChecked());};QObject::connect(method,QOverload<int>::of(&QComboBox::currentIndexChanged),&dialog,[&](int){update();});QObject::connect(knn,QOverload<int>::of(&QSpinBox::valueChanged),&dialog,[&](int){update();});QObject::connect(autoVariogram,&QCheckBox::toggled,&dialog,[&](bool){update();});update();
    auto* run=new QPushButton("Create DFM with these settings");root->addWidget(run);auto* cancel=new QPushButton("Cancel");root->addWidget(cancel);QObject::connect(cancel,&QPushButton::clicked,&dialog,&QDialog::reject);QObject::connect(run,&QPushButton::clicked,&dialog,[&](){
        if(minSupport->value()>maxSupport->value()||radius->value()/step->value()>64||(method->currentData().toInt()==4&&!autoVariogram->isChecked()&&nugget->value()>sill->value())){QMessageBox::warning(&dialog,"DFM settings","Minimum support must not exceed maximum. Support radius must not exceed 64 cells. Kriging nugget must not exceed sill.");return;}QSet<int> chosen;for(auto* check:classes)if(check->isChecked())chosen.insert(check->property("code").toInt());if(chosen.isEmpty()){QMessageBox::warning(&dialog,"DFM classes","Choose at least one Building class.");return;}
        auto& p=settings.parameters;p.surfaceMaximum=true;p.requireConflictReview=true;p.dfmMinimumMerge=mode->currentData().toBool();p.gridStep=step->value();p.dfmFill.method=DfmFillMethod(method->currentData().toInt());p.interpolateEmptyCells=p.dfmFill.method!=DfmFillMethod::None;p.dfmFill.radius=radius->value();p.dfmFill.maximumLocalRange=range->value();p.dfmFill.maximumMeanDeviation=deviation->value();p.dfmFill.minimumSupport=unsigned(minSupport->value());p.dfmFill.maximumSupport=unsigned(maxSupport->value());p.dfmFill.requireSurroundingSupport=surrounding->isChecked();p.maximumInterpolationEdgeLength=edge->value();p.krigingNeighbours=knn->value();p.krigingModel=model->currentIndex();p.krigingAutoParameters=autoVariogram->isChecked();p.krigingRange=krange->value();p.krigingSill=sill->value();p.krigingNugget=nugget->value();settings.buildingClasses=chosen;dialog.accept();});return dialog.exec()==QDialog::Accepted;
}
}
